// VR Desktop relay server.
//
// * Serves the WebXR client (mac/Web) over HTTP; TLS is terminated by the Kubernetes ingress
//   (Let's Encrypt), so the Quest browser gets a trusted certificate.
// * /ws is a WebSocket rendezvous: the Mac app connects as role=host, the Quest page as
//   role=client, both with the same secret room code (generated by the Mac, shown as the
//   link https://<host>/#<room>). Offers from clients are forwarded to the host and answers back.
//   Only signaling passes through here; the video goes directly from the Mac to the Quest.
//
// Env: PORT (default 8080), WEB_ROOT (default ../mac/Web).
'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { WebSocketServer } = require('ws');

const PORT = parseInt(process.env.PORT || '8080', 10);
const WEB_ROOT = path.resolve(process.env.WEB_ROOT || path.join(__dirname, '..', 'mac', 'Web'));
const ROOM_RE = /^[A-Za-z0-9_-]{16,128}$/;
const MAX_MSG = 256 * 1024;
const MAX_CLIENTS_PER_ROOM = 8;

const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css', '.png': 'image/png', '.svg': 'image/svg+xml' };

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  if (url.pathname === '/healthz') { res.writeHead(200); return res.end('ok'); }
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    return res.end('{"error":"not found"}');
  }
  const name = url.pathname === '/' ? 'index.html' : url.pathname.slice(1);
  if (name.includes('/') || name.includes('..')) { res.writeHead(404); return res.end(); }
  fs.readFile(path.join(WEB_ROOT, name), (err, data) => {
    if (err) { res.writeHead(404); return res.end('not found'); }
    res.writeHead(200, {
      'Content-Type': MIME[path.extname(name)] || 'application/octet-stream',
      'Cache-Control': 'no-cache',
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'no-referrer',
    });
    res.end(req.method === 'HEAD' ? undefined : data);
  });
});

// room -> { host: WebSocket|null, clients: Map<id, WebSocket> }
const rooms = new Map();
function room(code) {
  let r = rooms.get(code);
  if (!r) { r = { host: null, clients: new Map() }; rooms.set(code, r); }
  return r;
}
function gc(code) {
  const r = rooms.get(code);
  if (r && !r.host && r.clients.size === 0) rooms.delete(code);
}
function send(ws, obj) { if (ws && ws.readyState === ws.OPEN) ws.send(JSON.stringify(obj)); }

const wss = new WebSocketServer({ server, path: '/ws', maxPayload: MAX_MSG });

wss.on('connection', (ws, req) => {
  const url = new URL(req.url, 'http://x');
  const role = url.searchParams.get('role');
  const code = url.searchParams.get('room') || '';
  if (!ROOM_RE.test(code) || (role !== 'host' && role !== 'client')) {
    send(ws, { type: 'error', message: 'neplatný požadavek' });
    return ws.close(1008);
  }
  const r = room(code);
  ws.isAlive = true;
  ws.on('pong', () => { ws.isAlive = true; });

  if (role === 'host') {
    if (r.host) r.host.close(4000, 'replaced');
    r.host = ws;
    log('host connected', code);
    ws.on('message', data => {
      let m; try { m = JSON.parse(data); } catch { return; }
      if (m.type === 'answer' || m.type === 'error') {
        const c = r.clients.get(m.to);
        send(c, { type: m.type, sdp: m.sdp, message: m.message });
      }
    });
    ws.on('close', () => {
      if (r.host === ws) r.host = null;
      log('host disconnected', code);
      gc(code);
    });
    return;
  }

  // client
  if (r.clients.size >= MAX_CLIENTS_PER_ROOM) {
    send(ws, { type: 'error', message: 'příliš mnoho připojení' });
    return ws.close(1013);
  }
  const id = crypto.randomUUID();
  r.clients.set(id, ws);
  ws.on('message', data => {
    let m; try { m = JSON.parse(data); } catch { return; }
    if (m.type !== 'offer' || typeof m.sdp !== 'string') return;
    if (!r.host) return send(ws, { type: 'error', message: 'Mac není připojený k serveru' });
    send(r.host, { type: 'offer', sdp: m.sdp, from: id });
  });
  ws.on('close', () => { r.clients.delete(id); gc(code); });
});

// Keepalive so idle host connections survive ingress/load-balancer timeouts.
setInterval(() => {
  for (const ws of wss.clients) {
    if (!ws.isAlive) { ws.terminate(); continue; }
    ws.isAlive = false;
    ws.ping();
  }
}, 25000).unref();

function log(...a) { console.log(new Date().toISOString(), ...a.map(x => (typeof x === 'string' && ROOM_RE.test(x) ? x.slice(0, 4) + '…' : x))); }

server.listen(PORT, () => log(`listening on :${PORT}, web root ${WEB_ROOT}`));
for (const sig of ['SIGTERM', 'SIGINT']) process.on(sig, () => { server.close(); wss.close(); process.exit(0); });
